1	use ecow::{EcoString, EcoVec, eco_vec};
2	use typst_library::diag::{SourceResult, bail, warning};
3	use typst_library::engine::Engine;
4	use typst_library::foundations::{Content, Packed, StyleChain, Target, TargetElem};
5	use typst_library::introspection::{SplitLocator, TagElem};
6	use typst_library::layout::{
7	    Abs, Axes, BlockBody, BlockElem, BoxElem, HElem, Region, Size,
8	};
9	use typst_library::routines::Pair;
10	use typst_library::text::{
11	    LinebreakElem, SmartQuoteElem, SmartQuoter, SmartQuotes, SpaceElem, TextElem,
12	    is_default_ignorable,
13	};
14	use typst_syntax::Span;
15	use typst_utils::SliceExt;
16	
17	use crate::fragment::{html_block_fragment, html_inline_fragment, html_math_fragment};
18	use crate::{
19	    FrameElem, HtmlElem, HtmlElement, HtmlFrame, HtmlNode, attr, css, property, tag,
20	};
21	
22	/// What and how to convert.
23	pub enum ConversionLevel<'a> {
24	    /// Converts the top-level nodes or children of a block-level element. The
25	    /// conversion has its own local smart quoting state and space protection.
26	    Block,
27	    /// Converts the children of an inline-level HTML element as part of a
28	    /// larger context with shared smart quoting state and shared space
29	    /// protection.
30	    Inline(&'a mut SmartQuoter),
31	}
32	
33	/// How to emit whitespace.
34	#[derive(Debug, Copy, Clone, Eq, PartialEq, Hash)]
35	pub enum Whitespace {
36	    /// Ensures that whitespace that would otherwise be collapsed by HTML
37	    /// rendering engines[^1] is protected by spans with `white-space:
38	    /// pre-wrap`. The affected by whitespace are ASCII spaces and ASCII tabs.
39	    ///
40	    /// Tries to emit spans only when necessary.
41	    /// - ASCII tabs and consecutive sequences of spaces and/or tabs are always
42	    ///   wrapped in spans in this mode. This happens directly during
43	    ///   conversion.
44	    /// - Single ASCII spaces are only wrapped if they aren't supported by
45	    ///   normal elements on both sides. This happens in a separate pass that
46	    ///   runs for the whole block-level context as doing this properly needs
47	    ///   lookahead and lookbehind across different levels of the element
48	    ///   hierarchy.
49	    ///
50	    /// [^1]: <https://www.w3.org/TR/css-text-3/#white-space-rules>
51	    Normal,
52	    /// The whitespace is emitted as-is. This happens in
53	    /// - `<pre>` elements as they already have `white-space: pre`,
54	    /// - raw and escapable raw text elements as normal white space rules do not
55	    ///   apply to them.
56	    Pre,
57	}
58	
59	/// Converts realized content into HTML nodes.
60	pub fn convert_to_nodes<'a>(
61	    engine: &mut Engine,
62	    locator: &mut SplitLocator,
63	    children: impl IntoIterator<Item = Pair<'a>>,
64	    level: ConversionLevel,
65	    whitespace: Whitespace,
66	) -> SourceResult<EcoVec<HtmlNode>> {
67	    let block = matches!(level, ConversionLevel::Block);
68	    let mut converter = Converter {
69	        engine,
70	        locator,
71	        quoter: match level {
72	            ConversionLevel::Inline(quoter) => quoter,
73	            ConversionLevel::Block => &mut SmartQuoter::new(),
74	        },
75	        whitespace,
76	        output: EcoVec::new(),
77	        trailing: None,
78	    };
79	
80	    for (child, styles) in children {
81	        handle(&mut converter, child, styles)?;
82	    }
83	
84	    let mut nodes = converter.finish();
85	    if block && whitespace == Whitespace::Normal {
86	        protect_spaces(&mut nodes);
87	    }
88	
89	    Ok(nodes)
90	}
91	
92	/// Converts one element into HTML node(s).
93	fn handle(
94	    converter: &mut Converter,
95	    child: &Content,
96	    styles: StyleChain,
97	) -> SourceResult<()> {
98	    if let Some(elem) = child.to_packed::<TagElem>() {
99	        converter.push(elem.tag.clone());
100	    } else if let Some(elem) = child.to_packed::<HtmlElem>() {
101	        handle_html_elem(converter, elem, styles)?;
102	    } else if child.is::<SpaceElem>() {
103	        converter.push(HtmlNode::text(' ', child.span()));
104	    } else if let Some(elem) = child.to_packed::<TextElem>() {
105	        let text = if let Some(case) = styles.get(TextElem::case) {
106	            case.apply(&elem.text).into()
107	        } else {
108	            elem.text.clone()
109	        };
110	        handle_text(converter, text, elem.span());
111	    } else if let Some(elem) = child.to_packed::<HElem>()
112	        && elem.amount.is_zero()
113	    {
114	        // Nothing to do for zero-sized spacing. This is sometimes used to
115	        // destruct spaces, e.g. in footnotes. See [`HElem::hole`].
116	    } else if let Some(elem) = child.to_packed::<LinebreakElem>() {
117	        converter.push(match converter.whitespace {
118	            Whitespace::Normal => HtmlElement::new(tag::br).spanned(elem.span()).into(),
119	            Whitespace::Pre => HtmlNode::text("\n", elem.span()),
120	        });
121	    } else if let Some(elem) = child.to_packed::<SmartQuoteElem>() {
122	        let double = elem.double.get(styles);
123	        let quote = if elem.enabled.get(styles) {
124	            let before = last_char(&converter.output);
125	            let quotes = SmartQuotes::get(
126	                elem.quotes.get_ref(styles),
127	                styles.get(TextElem::lang),
128	                styles.get(TextElem::region),
129	                elem.alternative.get(styles),
130	            );
131	            converter.quoter.quote(before, &quotes, double)
132	        } else {
133	            SmartQuotes::fallback(double)
134	        };
135	        handle_text(converter, quote.into(), child.span());
136	    } else if let Some(elem) = child.to_packed::<BoxElem>() {
137	        handle_box(converter, elem, styles)?;
138	    } else if let Some(elem) = child.to_packed::<BlockElem>() {
139	        handle_block(converter, elem, styles)?;
140	    } else if let Some(elem) = child.to_packed::<FrameElem>() {
141	        let locator = converter.locator.next(&elem.span());
142	        let style = TargetElem::target.set(Target::Paged).wrap();
143	        let frame = (converter.engine.library.routines.layout_frame)(
144	            converter.engine,
145	            &elem.body,
146	            locator,
147	            styles.chain(&style),
148	            Region::new(Size::splat(Abs::inf()), Axes::splat(false)),
149	        )?;
150	        let mut node = HtmlFrame::new(frame, styles, elem.span()).into();
151	        // A frame is block-level by default like a Typst `image`. It can
152	        // be wrapped in a `box` to omit the `display` annotation.
153	        make_block_level(&mut node).unwrap();
154	        converter.push(node);
155	    } else {
156	        converter.engine.sink.warn(warning!(
157	            child.span(),
158	            "{} was ignored during HTML export",
159	            child.elem().name(),
160	        ));
161	    }
162	    Ok(())
163	}
164	
165	/// Handles an HTML element.
166	fn handle_html_elem(
167	    converter: &mut Converter,
168	    elem: &Packed<HtmlElem>,
169	    styles: StyleChain,
170	) -> SourceResult<()> {
171	    // See the docs of `HtmlElem::role` for why we filter out roles for `<p>`
172	    // elements.
173	    let role = styles.get_cloned(HtmlElem::role).filter(|_| elem.tag != tag::p);
174	
175	    let mut children = EcoVec::new();
176	    if let Some(body) = elem.body.get_ref(styles) {
177	        let whitespace = if converter.whitespace == Whitespace::Pre
178	            || elem.tag == tag::pre
179	            || tag::is_raw(elem.tag)
180	            || tag::is_escapable_raw(elem.tag)
181	        {
182	            Whitespace::Pre
183	        } else {
184	            Whitespace::Normal
185	        };
186	
187	        // The `role` attribute should only apply to the first element in the
188	        // hierarchy. Thus, we unset it for children if it is currently set.
189	        let unset;
190	        let styles = if role.is_some() {
191	            unset = HtmlElem::role.set(None).wrap();
192	            styles.chain(&unset)
193	        } else {
194	            styles
195	        };
196	
197	        if property::Display::default_for(elem.tag) == Some(property::Display::Block) {
198	            children = html_block_fragment(
199	                converter.engine,
200	                body,
201	                converter.locator.next(&elem.span()),
202	                styles,
203	                whitespace,
204	            )?;
205	
206	            // Block-level elements reset the inline state. This part is
207	            // unfortunately untested as it's currently not possible to
208	            // create inline-level content next to block-level content
209	            // without a paragraph automatically appearing.
210	            *converter.quoter = SmartQuoter::new();
211	        } else if tag::mathml::is_mathml(elem.tag) {
212	            children = html_math_fragment(
213	                converter.engine,
214	                body,
215	                converter.locator,
216	                converter.quoter,
217	                styles,
218	                whitespace,
219	            )?;
220	        } else {
221	            children = html_inline_fragment(
222	                converter.engine,
223	                body,
224	                converter.locator,
225	                converter.quoter,
226	                styles,
227	                whitespace,
228	            )?;
229	        }
230	    }
231	
232	    let mut attrs = elem.attrs.get_cloned(styles);
233	    if let Some(role) = role {
234	        attrs.push(attr::role, role);
235	    }
236	
237	    converter.push(HtmlElement {
238	        tag: elem.tag,
239	        attrs,
240	        css: elem.css.get_cloned(styles),
241	        children,
242	        parent: elem.parent,
243	        span: elem.span(),
244	        pre_span: false,
245	    });
246	
247	    Ok(())
248	}
249	
250	/// Handles arbitrary text while taking care that no whitespace within will be
251	/// collapsed by browsers.
252	fn handle_text(converter: &mut Converter, text: EcoString, span: Span) {
253	    /// Special kinds of characters.
254	    #[derive(Debug, Copy, Clone, Eq, PartialEq)]
255	    enum Kind {
256	        /// ASCII space.
257	        Space,
258	        /// ASCII tab.
259	        Tab,
260	        /// CR, LF, or CR + LF.
261	        Newline,
262	        /// A Unicode default-ignorable. Does not protect spaces from
263	        /// collapsing.
264	        Ignorable,
265	    }
266	
267	    impl Kind {
268	        fn of(c: char) -> Option<Kind> {
269	            match c {
270	                ' ' => Some(Kind::Space),
271	                '\t' => Some(Kind::Tab),
272	                '\r' | '\n' => Some(Kind::Newline),
273	                c if is_default_ignorable(c) => Some(Kind::Ignorable),
274	                _ => None,
275	            }
276	        }
277	    }
278	
279	    if converter.whitespace == Whitespace::Pre {
280	        converter.push(HtmlNode::Text(text, span));
281	        return;
282	    }
283	
284	    let mut emitted = 0;
285	    let mut prev_kind = None;
286	
287	    for (i, c) in text.char_indices() {
288	        let kind = Kind::of(c);
289	        let prev_kind = prev_kind.replace(kind);
290	        let Some(kind) = kind else { continue };
291	
292	        // A space that is surrounded by normal (i.e. not special) characters is
293	        // already protected and doesn't need further treatment.
294	        if kind == Kind::Space
295	            && let Some(None) = prev_kind
296	            && let Some(after) = text[i + 1..].chars().next()
297	            && Kind::of(after).is_none()
298	        {
299	            continue;
300	        }
301	
302	        // Emit the unspecial text up to the special character.
303	        if emitted < i {
304	            converter.push_text(&text[emitted..i], span);
305	            emitted = i;
306	        }
307	
308	        // Process the special character.
309	        match kind {
310	            Kind::Space => converter.push_text(' ', span),
311	            Kind::Tab => converter.push_text('\t', span),
312	            Kind::Newline => {
313	                if c == '\r' && text[i + 1..].starts_with('\n') {
314	                    // Skip the CR because the LF will already turn into
315	                    // a `<br>`.
316	                    emitted += 1;
317	                    continue;
318	                }
319	                converter.push(HtmlElement::new(tag::br).spanned(span));
320	            }
321	            Kind::Ignorable => converter.push_text(c, span),
322	        }
323	        emitted += c.len_utf8();
324	    }
325	
326	    // Push the remaining unspecial text.
327	    if emitted < text.len() {
328	        converter.push_text(
329	            // Try to reuse the `EcoString` if possible.
330	            if emitted == 0 { text } else { text[emitted..].into() },
331	            span,
332	        );
333	    }
334	}
335	
336	/// Processes a box element.
337	fn handle_box(
338	    converter: &mut Converter,
339	    elem: &Packed<BoxElem>,
340	    styles: StyleChain,
341	) -> SourceResult<()> {
342	    let mut children = EcoVec::new();
343	    if let Some(body) = elem.body.get_ref(styles) {
344	        children = html_inline_fragment(
345	            converter.engine,
346	            body,
347	            converter.locator,
348	            converter.quoter,
349	            styles,
350	            converter.whitespace,
351	        )?;
352	
353	        if let Some(node) = to_lone_element(&mut children) {
354	            make_inline_level(node);
355	            converter.extend(children);
356	            return Ok(());
357	        }
358	    }
359	
360	    converter.push(
361	        // TODO: This is rather incomplete.
362	        HtmlElement::new(tag::span)
363	            .with_css(css::Properties::new().with("display", "inline-block"))
364	            .with_children(children)
365	            .spanned(elem.span()),
366	    );
367	
368	    Ok(())
369	}
370	
371	/// Ensures a lone HTML element/frame renders inline.
372	///
373	/// Paragraphs only allow "Phrasing content". The default display properties
374	/// that exists for valid phrasing content are `none`, `inline`, `inline-block`,
375	/// `contents`, `ruby`, and `inline math`. These can all be left as-is.
376	///
377	/// If, however, the `display` property was set to something like `block`
378	/// through a Typst `block` element, we need to unset it. Further, if a math
379	/// element has its `display` attribute set to `block`, then we need to
380	/// override it.
381	fn make_inline_level(node: &mut HtmlNode) {
382	    let mode = if let HtmlNode::Element(element) = node
383	        && element.tag == tag::mathml::math
384	        && element.attrs.get(attr::mathml::display).is_some_and(|v| v == "block")
385	    {
386	        Some(property::Display::InlineMath)
387	    } else {
388	        None
389	    };
390	    set_display(node, mode);
391	}
392	
393	/// Processes a block element.
394	fn handle_block(
395	    converter: &mut Converter,
396	    elem: &Packed<BlockElem>,
397	    styles: StyleChain,
398	) -> SourceResult<()> {
399	    let body = match elem.body.get_ref(styles) {
400	        None => None,
401	        Some(BlockBody::Content(body)) => Some(body),
402	        // These are only generated by native `typst-layout` show rules.
403	        Some(BlockBody::SingleLayouter(_) | BlockBody::MultiLayouter(_)) => {
404	            bail!(
405	                elem.span(),
406	                "blocks with layout routines should not occur in \
407	                 HTML export – this is a bug";
408	            )
409	        }
410	    };
411	
412	    let mut children = EcoVec::new();
413	    if let Some(body) = body {
414	        children = html_block_fragment(
415	            converter.engine,
416	            body,
417	            converter.locator.next(&elem.span()),
418	            styles,
419	            converter.whitespace,
420	        )?;
421	
422	        if let Some(node) = to_lone_element(&mut children)
423	            && make_block_level(node).is_ok()
424	        {
425	            converter.extend(children);
426	            return Ok(());
427	        }
428	    }
429	
430	    converter.push(
431	        // TODO: This is rather incomplete.
432	        HtmlElement::new(tag::div)
433	            .with_children(children)
434	            .spanned(elem.span()),
435	    );
436	
437	    Ok(())
438	}
439	
440	/// Ensures a lone HTML element/frame renders as its own block.
441	///
442	/// Configures the `display` property of the HTML node (if it is an element or
443	/// frame).
444	fn make_block_level(node: &mut HtmlNode) -> Result<(), Unblockable> {
445	    let default = match node {
446	        // A math element's default display property depends on its `display`
447	        // attribute.
448	        HtmlNode::Element(element)
449	            if element.tag == tag::mathml::math
450	                && element
451	                    .attrs
452	                    .get(attr::mathml::display)
453	                    .is_some_and(|v| v == "block") =>
454	        {
455	            Some(property::Display::BlockMath)
456	        }
457	        HtmlNode::Element(element) => property::Display::default_for(element.tag),
458	        HtmlNode::Frame(_) => Some(property::Display::Inline),
459	        _ => return Err(Unblockable),
460	    };
461	
462	    let mode = match default {
463	        // These can be left unchanged / have `display` unset because they are
464	        // either invisible or already render in a block-level way.
465	        Some(
466	            property::Display::None
467	            | property::Display::Block
468	            | property::Display::Table
469	            | property::Display::ListItem
470	            | property::Display::Contents
471	            | property::Display::BlockMath,
472	        ) => None,
473	
474	        // These must be promoted to `block`.
475	        None | Some(property::Display::Inline | property::Display::InlineBlock) => {
476	            Some(property::Display::Block)
477	        }
478	        Some(property::Display::InlineMath) => Some(property::Display::BlockMath),
479	
480	        // These can't be promoted. They are instead wrapped in a `<div>`.
481	        _ => return Err(Unblockable),
482	    };
483	
484	    set_display(node, mode);
485	    Ok(())
486	}
487	
488	/// Indicates that an element can be made block-level with a `display` property.
489	#[derive(Debug, Copy, Clone)]
490	struct Unblockable;
491	
492	/// Whether, apart from tags, the nodes comprise a single element or frame.
493	fn to_lone_element(nodes: &mut EcoVec<HtmlNode>) -> Option<&mut HtmlNode> {
494	    let (start, end) = nodes.split_prefix_suffix(|node| matches!(node, HtmlNode::Tag(_)));
495	    matches!(&nodes[start..end], [HtmlNode::Element(_) | HtmlNode::Frame(_)])
496	        .then(|| &mut nodes.make_mut()[start])
497	}
498	
499	/// Sets the CSS `display` property for an element or frame.
500	fn set_display(node: &mut HtmlNode, display: Option<property::Display>) {
501	    let css = match node {
502	        HtmlNode::Element(element) => &mut element.css,
503	        HtmlNode::Frame(frame) => &mut frame.css,
504	        _ => return,
505	    };
506	    match display {
507	        Some(display) => css.push("display", display.as_str()),
508	        None => css.remove("display"),
509	    }
510	}
511	
512	/// State during conversion.
513	struct Converter<'a, 'y, 'z> {
514	    engine: &'a mut Engine<'y>,
515	    locator: &'a mut SplitLocator<'z>,
516	    quoter: &'a mut SmartQuoter,
517	    whitespace: Whitespace,
518	    output: EcoVec<HtmlNode>,
519	    trailing: Option<TrailingWhitespace>,
520	}
521	
522	/// Keeps track of a trailing whitespace in the output.
523	struct TrailingWhitespace {
524	    /// If `true`, the trailing whitespace consists of exactly one ASCII space.
525	    single: bool,
526	    /// The trailing whitespace starts at `output[from..]`.
527	    from: usize,
528	}
529	
530	impl Converter<'_, '_, '_> {
531	    /// Returns the converted nodes.
532	    fn finish(mut self) -> EcoVec<HtmlNode> {
533	        self.flush_whitespace();
534	        self.output
535	    }
536	
537	    /// Pushes a node, taking care to protect consecutive whitespace.
538	    fn push(&mut self, node: impl Into<HtmlNode>) {
539	        let node = node.into();
540	
541	        if let HtmlNode::Text(text, _) = &node
542	            && (text == " " || text == "\t")
543	        {
544	            if let Some(ws) = &mut self.trailing {
545	                ws.single = false;
546	            } else {
547	                self.trailing = Some(TrailingWhitespace {
548	                    single: text == " ",
549	                    from: self.output.len(),
550	                });
551	            }
552	        } else if !matches!(node, HtmlNode::Tag(_)) {
553	            self.flush_whitespace();
554	        }
555	
556	        self.output.push(node);
557	    }
558	
559	    /// Pushes multiples nodes.
560	    fn extend(&mut self, nodes: impl IntoIterator<Item = HtmlNode>) {
561	        for node in nodes {
562	            self.push(node);
563	        }
564	    }
565	
566	    /// Shorthand for pushing a text node.
567	    fn push_text(&mut self, text: impl Into<EcoString>, span: Span) {
568	        self.push(HtmlNode::text(text.into(), span));
569	    }
570	
571	    /// If there is trailing whitespace in need of protection, protects it.
572	    ///
573	    /// Does not protect single ASCII spaces. Those are handled in a separate
574	    /// pass as they are more complex and require lookahead. See the
575	    /// documentation of [`Whitespace`] for more information.
576	    fn flush_whitespace(&mut self) {
577	        if self.whitespace == Whitespace::Normal
578	            && let Some(TrailingWhitespace { single: false, from }) = self.trailing.take()
579	        {
580	            let nodes: EcoVec<_> = self.output[from..].iter().cloned().collect();
581	            self.output.truncate(from);
582	            self.output.push(HtmlNode::Element(pre_wrap(nodes)));
583	        }
584	    }
585	}
586	
587	/// Protects all spaces in the given block-level `nodes` against collapsing.
588	///
589	/// Does not recurse into block-level elements as those are separate contexts
590	/// with their own space protection.
591	fn protect_spaces(nodes: &mut EcoVec<HtmlNode>) {
592	    let mut p = Protector::new();
593	    p.visit_nodes(nodes);
594	    p.collapsing();
595	}
596	
597	/// A state machine for whitespace protection.
598	enum Protector<'a> {
599	    Collapsing,
600	    Supportive,
601	    Space(&'a mut HtmlNode),
602	}
603	
604	impl<'a> Protector<'a> {
605	    /// Creates a new protector.
606	    fn new() -> Self {
607	        Self::Collapsing
608	    }
609	
610	    /// Visits the given nodes and protects single spaces that need to be saved
611	    /// from collapsing.
612	    fn visit_nodes(&mut self, nodes: &'a mut EcoVec<HtmlNode>) {
613	        for node in nodes.make_mut().iter_mut() {
614	            match node {
615	                HtmlNode::Tag(_) => {}
616	                HtmlNode::Text(text, _) => {
617	                    if text == " " {
618	                        match self {
619	                            Self::Collapsing => {
620	                                protect_space(node);
621	                                *self = Self::Supportive;
622	                            }
623	                            Self::Supportive => {
624	                                *self = Self::Space(node);
625	                            }
626	                            Self::Space(prev) => {
627	                                protect_space(prev);
628	                                *self = Self::Space(node);
629	                            }
630	                        }
631	                    } else if text.chars().any(|c| !is_default_ignorable(c)) {
632	                        self.supportive();
633	                    }
634	                }
635	                HtmlNode::Element(element) => {
636	                    if tag::is_whitespace_collapsing(element.tag) {
637	                        self.collapsing();
638	                    } else if tag::is_replaced(element.tag) {
639	                        self.supportive();
640	                    } else if !element.pre_span {
641	                        // Recursively visit the children of inline-level
642	                        // elements while making sure to not revisit pre-wrapped
643	                        // spans that we've generated ourselves.
644	                        self.visit_nodes(&mut element.children);
645	                    }
646	                }
647	                HtmlNode::Frame(_) => self.supportive(),
648	            }
649	        }
650	    }
651	
652	    /// Called when visiting an element that would collapse adjacent single
653	    /// spaces. A preceding, if any, and succeeding, if any, single space will
654	    /// then be protected .
655	    fn collapsing(&mut self) {
656	        if let Self::Space(node) = std::mem::replace(self, Self::Collapsing) {
657	            protect_space(node);
658	        }
659	    }
660	
661	    /// Called when visiting an element that supports adjacent single spaces.
662	    fn supportive(&mut self) {
663	        *self = Self::Supportive;
664	    }
665	}
666	
667	/// Protects a single spaces against collapsing.
668	fn protect_space(node: &mut HtmlNode) {
669	    *node = pre_wrap(eco_vec![node.clone()]).into();
670	}
671	
672	/// Wraps a collection of whitespace nodes in a
673	/// `<span style="white-space: pre-wrap">..</span>` to avoid them being
674	/// collapsed by HTML rendering engines.
675	fn pre_wrap(nodes: EcoVec<HtmlNode>) -> HtmlElement {
676	    let span = Span::find(nodes.iter().map(|c| c.span()));
677	    let mut elem = HtmlElement::new(tag::span)
678	        .with_css(css::Properties::new().with("white-space", "pre-wrap"))
679	        .with_children(nodes)
680	        .spanned(span);
681	    elem.pre_span = true;
682	    elem
683	}
684	
685	/// Returns the last non-default ignorable character from the passed nodes.
686	fn last_char(nodes: &[HtmlNode]) -> Option<char> {
687	    for node in nodes.iter().rev() {
688	        if let Some(c) = match node {
689	            HtmlNode::Text(s, _) => s.chars().rev().find(|&c| !is_default_ignorable(c)),
690	            HtmlNode::Element(e) => last_char(&e.children),
691	            _ => None,
692	        } {
693	            return Some(c);
694	        }
695	    }
696	    None
697	}
